c.setSoTimeout(idleMs);                  // 유휴 한도 — 없으면 스레드가 안 돌아온다
while (true) {
    // 머리를 읽는다 (9.2절)
    ByteArrayOutputStream head = readHead(raw);
    if (head.size() == 0) break;         // 상대가 닫았다

    boolean wantClose = head.toString("ISO-8859-1").toLowerCase()
                            .contains("connection: close");
    byte[] body = ("ok " + (served + 1) + "\n").getBytes();
    // 상태 줄 + Content-Length + (필요하면) Connection: close + 빈 줄 + 본문
    write(os, body, wantClose);
    served++;
    if (wantClose) break;
}
